import { Table, StringColumn, IntegerColumn, ConditionsColumn, GenericColumn } from '../../db'

export const sys_retry_policy = Table({
    name: 'sys_retry_policy',
    extends: 'sys_metadata',
    label: 'Retry Policy',
    allowWebServiceAccess: true,
    schema: {
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 40,
        }),
        count: IntegerColumn({
            mandatory: false,
            label: 'Count',
        }),
        interval: GenericColumn({
            mandatory: false,
            label: 'Interval (seconds)',
            column_type: 'long',
            maxLength: 40,
        }),
        max_elapsed_time: IntegerColumn({
            mandatory: false,
            label: 'Max Elapsed Time (seconds)',
        }),
        retry_strategy: StringColumn({
            mandatory: false,
            label: 'Retry Strategy',
            default: 'fixed_time_interval',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 40,
            choices: {
                fixed_time_interval: {
                    label: 'Fixed Interval',
                    sequence: 0,
                },
                exponential_backoff: {
                    label: 'Exponential Backoff',
                    sequence: 0,
                },
                retry_after: {
                    label: 'Honor "Retry-After" Header',
                    sequence: 0,
                },
            },
        }),
        connection_type: StringColumn({
            mandatory: false,
            label: 'Connection Type',
            default: 'http_retry_conditions',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 40,
            choices: {
                http_retry_conditions: {
                    label: 'HTTP',
                    sequence: 0,
                },
                jdbc_retry_conditions: {
                    label: 'JDBC',
                    sequence: 0,
                },
                basic_retry_conditions: {
                    label: 'Basic(SFTP)',
                    sequence: 0,
                },
            },
        }),
        condition: ConditionsColumn({
            mandatory: false,
            label: 'Conditions',
            dependent: 'connection_type',
            maxLength: 4000,
        }),
        restrict_to: StringColumn({
            mandatory: false,
            label: 'Restrict To',
            default: 'http_method,status_code,error,response_body,response_headers',
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 120,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            column_type: 'GUID',
        }),
    },
})
